import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.List;
import java.util.stream.Stream;

/** Shared copy logic for the resources/testResources goals. */
abstract class AbstractResourcesMojo extends AbstractMojo {

    protected MavenProject project;

    // Absorb configuration injected by spring-boot-starter-parent.
    protected String propertiesEncoding;
    protected List<String> delimiters;
    protected boolean useDefaultDelimiters;

    protected abstract List<Resource> resources();

    protected abstract String outputDirectory();

    public void execute() throws MojoExecutionException {
        String outDir = outputDirectory();
        if (outDir == null) {
            return;
        }
        Path output = Paths.get(outDir);
        List<Resource> resources = resources();
        if (resources == null) {
            return;
        }
        for (Resource resource : resources) {
            if (resource == null || resource.getDirectory() == null) {
                continue;
            }
            Path source = Paths.get(resource.getDirectory());
            if (!Files.isDirectory(source)) {
                continue;
            }
            try (Stream<Path> stream = Files.walk(source)) {
                for (Path p : (Iterable<Path>) stream::iterator) {
                    if (!Files.isRegularFile(p)) {
                        continue;
                    }
                    Path target = output.resolve(source.relativize(p).toString());
                    Files.createDirectories(target.getParent());
                    Files.copy(p, target, StandardCopyOption.REPLACE_EXISTING);
                }
            } catch (IOException e) {
                throw new MojoExecutionException("Failed to copy resources", e);
            }
        }
    }
