import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.project.MavenProject;

import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** Goal "compile": compiles src/main/java with the JDK compiler. */
public class CompileMojo extends AbstractMojo {

    private MavenProject project;

    // Absorb configuration injected by spring-boot-starter-parent.
    private boolean parameters;

    public void execute() throws MojoExecutionException {
        Path sourceDir = project.getBasedir().toPath().resolve("src/main/java");
        if (!Files.isDirectory(sourceDir)) {
            return;
        }
        File outDir = new File(project.getBuild().getOutputDirectory());
        outDir.mkdirs();

        List<String> sources;
        try (Stream<Path> stream = Files.walk(sourceDir)) {
            sources = stream.filter(p -> p.toString().endsWith(".java") && Files.isRegularFile(p))
                    .map(p -> p.toAbsolutePath().toString())
                    .collect(Collectors.toList());
        } catch (Exception e) {
            throw new MojoExecutionException("Failed to list sources", e);
        }
        if (sources.isEmpty()) {
            return;
        }

        List<String> classpath;
        try {
            classpath = new ArrayList<>(project.getCompileClasspathElements());
        } catch (Exception e) {
            throw new MojoExecutionException("Failed to resolve compile classpath", e);
        }

        List<String> options = new ArrayList<>();
        options.add("-classpath");
        options.add(String.join(File.pathSeparator, classpath));
        options.add("-d");
        options.add(outDir.getAbsolutePath());
        options.add("-encoding");
        options.add("UTF-8");
        options.add("-parameters");

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available");
        }
        StringWriter errors = new StringWriter();
        try (StandardJavaFileManager fileManager =
                     compiler.getStandardFileManager(null, null, StandardCharsets.UTF_8)) {
            Iterable<? extends JavaFileObject> units =
                    fileManager.getJavaFileObjectsFromStrings(sources);
            Boolean ok = compiler.getTask(errors, fileManager, null, options, null, units).call();
            if (!Boolean.TRUE.equals(ok)) {
                throw new MojoExecutionException("Compilation failed:\n" + errors);
            }
        } catch (MojoExecutionException e) {
            throw e;
        } catch (Exception e) {
            throw new MojoExecutionException("Compilation failed", e);
        }
        getLog().info("Compiled " + sources.size() + " source files to " + outDir);
    }
}
