import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.project.MavenProject;

import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;
import java.util.Properties;
import java.util.jar.Attributes;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;
import java.util.jar.Manifest;
import java.util.stream.Stream;

/** Goal "jar": packages the build output directory into the main jar. */
public class JarMojo extends AbstractMojo {

    private MavenProject project;

    // Absorb configuration injected by spring-boot-starter-parent.
    private Map<String, Object> archive;

    public void execute() throws MojoExecutionException {
        Path classesDir = new File(project.getBuild().getOutputDirectory()).toPath();
        File jarFile = new File(project.getBuild().getDirectory(),
                project.getBuild().getFinalName() + ".jar");
        jarFile.getParentFile().mkdirs();

        Manifest manifest = new Manifest();
        manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
        manifest.getMainAttributes().putValue("Created-By", "offline-jar-plugin");

        try (JarOutputStream jos = new JarOutputStream(new FileOutputStream(jarFile), manifest)) {
            if (Files.isDirectory(classesDir)) {
                try (Stream<Path> stream = Files.walk(classesDir)) {
                    for (Path p : (Iterable<Path>) stream::iterator) {
                        if (!Files.isRegularFile(p)) {
                            continue;
                        }
                        String entryName = classesDir.relativize(p).toString().replace(File.separatorChar, '/');
                        jos.putNextEntry(new JarEntry(entryName));
                        Files.copy(p, jos);
                        jos.closeEntry();
                    }
                }
            }
            String pomPropsPath = "META-INF/maven/" + project.getGroupId() + "/"
                    + project.getArtifactId() + "/pom.properties";
            Properties props = new Properties();
            props.setProperty("groupId", project.getGroupId());
            props.setProperty("artifactId", project.getArtifactId());
            props.setProperty("version", project.getVersion());
            jos.putNextEntry(new JarEntry(pomPropsPath));
            props.store(jos, null);
            jos.closeEntry();
        } catch (Exception e) {
            throw new MojoExecutionException("Failed to create jar", e);
        }
        project.getArtifact().setFile(jarFile);
        getLog().info("Building jar: " + jarFile.getAbsolutePath());
    }
}
